package com.shopstream.gateway;

import java.time.Duration;
import java.time.Instant;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class FixedWindowLimiter {

    private static final long WINDOW_SECONDS = 60;
    private final StringRedisTemplate redis;

    public FixedWindowLimiter(StringRedisTemplate redis) {
        this.redis = redis;
    }

    public boolean allow(String ip, String route, long limit) {
        long window = Instant.now().getEpochSecond() / WINDOW_SECONDS;
        String key = "rl:" + ip + ":" + route + ":" + window;
        Long count = redis.opsForValue().increment(key);
        if (count != null && count == 1L) {
            redis.expire(key, Duration.ofSeconds(WINDOW_SECONDS));
        }
        return count != null && count <= limit;
    }
}

package com.shopstream.cleanup;

import java.util.HashSet;
import java.util.Set;
import org.springframework.data.redis.core.Cursor;
import org.springframework.data.redis.core.ScanOptions;
import org.springframework.data.redis.core.StringRedisTemplate;

public class KeyCleaner {

    private final StringRedisTemplate redis;

    public KeyCleaner(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Deletes all keys matching a pattern, in small batches. */
    public long deleteSessions(String pattern) {
        ScanOptions options = ScanOptions.scanOptions().match(pattern).count(500).build();
        long deleted = 0;
        Set<String> batch = new HashSet<>();
        try (Cursor<String> cursor = redis.scan(options)) {
            while (cursor.hasNext()) {
                batch.add(cursor.next());
                if (batch.size() >= 500) {
                    deleted += flush(batch);
                }
            }
        }
        return deleted + flush(batch);
    }

    private long flush(Set<String> batch) {
        if (batch.isEmpty()) {
            return 0;
        }
        Long n = redis.unlink(batch);
        batch.clear();
        return n == null ? 0 : n;
    }
}

package com.shopstream.search;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public final class VectorBytes {

    private VectorBytes() {
    }

    /** Encodes floats as the little-endian FLOAT32 blob Redis expects. */
    public static byte[] toBlob(float[] vector) {
        ByteBuffer buffer = ByteBuffer.allocate(vector.length * Float.BYTES)
                .order(ByteOrder.LITTLE_ENDIAN);
        for (float value : vector) {
            buffer.putFloat(value);
        }
        return buffer.array();
    }

    public static float[] fromBlob(byte[] blob) {
        ByteBuffer buffer = ByteBuffer.wrap(blob).order(ByteOrder.LITTLE_ENDIAN);
        float[] vector = new float[blob.length / Float.BYTES];
        for (int i = 0; i < vector.length; i++) {
            vector[i] = buffer.getFloat();
        }
        return vector;
    }
}
